    private final JdbcTemplate jdbcTemplate;

    public ConsentRecordRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 按主体+用途+代次+记录键查询记录。
